<template>
  <section v-if="component" class="component-page">
    <RouterLink :to="{name:'supplier-assurance',query:{supplierId:component.supplier_id}}" class="back-link">← Supplier assurance</RouterLink>
    <header class="component-hero" data-guide="component-header">
      <div class="component-mark">{{ initials(component.name) }}</div>
      <div class="hero-copy"><p class="eyebrow">Third-party component</p><h1>{{ component.name }}</h1><p>{{ component.version||'Version not specified' }} · {{ component.component_type }} · supplied by <RouterLink :to="{name:'supplier-assurance',query:{supplierId:component.supplier_id}}">{{ supplier?.name||'Unknown supplier' }}</RouterLink></p></div>
      <div class="hero-actions"><AppButton class="embedded-guide-trigger" variant="secondary" size="sm" @click="startGuide"><span aria-hidden="true">?</span> Guide</AppButton><StatusBadge :label="supportState.label" :variant="supportState.variant" /></div>
    </header>

    <div class="summary-grid" data-guide="component-summary">
      <article><span>Product releases</span><strong>{{ traceability.length }}</strong></article><article><span>Assessments</span><strong>{{ assessments.length }}</strong></article><article><span>Vulnerabilities</span><strong>{{ vulnerabilities.length }}</strong></article><article><span>Maintainer notices</span><strong>{{ notifications.length }}</strong></article>
    </div>

    <div class="detail-grid">
      <main>
        <article class="card"><div class="section-head"><div><h2>Product usage</h2><p>Where this exact component record is integrated.</p></div></div><div v-if="!traceability.length" class="empty">No product releases are linked.</div><div v-else class="usage-list"><div v-for="row in traceability" :key="row.id" class="usage-row"><div><RouterLink :to="{name:'product-detail',params:{productId:row.product_id}}">{{ row.product_name }}</RouterLink><strong>{{ row.release_version }}</strong></div><div><span>{{ row.is_direct?'Direct':'Transitive' }}</span><span>{{ row.criticality }} criticality</span><span v-if="row.is_core_function">Core function</span></div><div><span>{{ row.sbom_file_name||'Manual link' }}</span><p>{{ row.usage_context||row.criticality_rationale }}</p></div></div></div></article>

        <article class="card"><div class="section-head"><div><h2>Due-diligence assessments</h2><p>Component-specific and supplier-wide assurance decisions.</p></div></div><div v-if="!assessments.length" class="empty warning">No assessment covers this component.</div><div v-else class="record-list"><RouterLink v-for="item in assessments" :key="item.id" :to="{name:'supplier-assessment-detail',params:{assessmentId:item.id}}" class="record-row"><div><strong>{{ item.title }}</strong><span>Version {{ item.system_version }} · valid until {{ item.valid_until||'not limited' }}</span></div><StatusBadge :label="item.reassessment_required?'Reassessment required':label(item.status)" :variant="item.reassessment_required?'warning':assessmentVariant(item.status)" /></RouterLink></div></article>

        <article class="card"><div class="section-head"><div><h2>Known vulnerabilities</h2><p>Automatically correlated from SBOM findings to every product using this component.</p></div></div><div v-if="!vulnerabilities.length" class="empty">No correlated vulnerabilities.</div><div v-else class="record-list"><div v-for="item in vulnerabilities" :key="item.finding_id" class="vulnerability-row"><div class="vulnerability-head"><div><strong>{{ item.vulnerability_id }}</strong><span>{{ item.title }} · {{ label(item.status||'reported') }}</span></div><div><StatusBadge v-if="item.is_known_exploited" label="Known exploited" variant="danger" /><StatusBadge :label="item.severity||'Unrated'" :variant="severityVariant(item.severity)" /></div></div><div class="affected"><span>Affects</span><RouterLink v-for="release in item.affected_releases" :key="release.release_id" :to="{name:'release-gate',params:{releaseId:release.release_id}}">{{ release.product_name }} · {{ release.release_version }}</RouterLink></div><small v-if="item.fixed_versions.length">Fixed versions: {{ item.fixed_versions.join(', ') }}</small></div></div></article>
      </main>

      <aside>
        <article class="card metadata"><h2>Identity</h2><dl><div><dt>Package URL</dt><dd>{{ component.purl||'Not provided' }}</dd></div><div><dt>CPE</dt><dd>{{ component.cpe||'Not provided' }}</dd></div><div><dt>Part number</dt><dd>{{ component.part_number||'Not provided' }}</dd></div><div><dt>Support ends</dt><dd>{{ component.support_end_date||'Not provided' }}</dd></div><div><dt>Update channel</dt><dd>{{ component.update_channel||'Not provided' }}</dd></div></dl></article>
        <article class="card metadata"><h2>Maintainer coordination</h2><div v-if="!notifications.length" class="empty">No notification history.</div><div v-for="notice in notifications" :key="notice.id" class="notice"><div><strong>{{ label(notice.status) }}</strong><span>{{ notice.notification_method }} · {{ notice.recipient }}</span></div><p>{{ notice.information_shared }}</p><small v-if="notice.notified_at">Sent {{ formatDate(notice.notified_at) }}</small></div></article>
        <article v-if="component.notes" class="card metadata"><h2>Notes</h2><p>{{ component.notes }}</p></article>
      </aside>
    </div>
  </section>
  <div v-else class="loading">Loading component traceability…</div>
</template>

<script setup lang="ts">
import { computed, onMounted, ref } from "vue";
import { RouterLink } from "vue-router";
import StatusBadge, { type BadgeVariant } from "@/components/StatusBadge.vue";
import AppButton from "@/components/AppButton.vue";
import { supplierAssessmentService as api } from "@/services/supplier-assessment-service";
import type { ComponentTraceability, ComponentVulnerabilityTrace, MaintainerNotification, Supplier, SupplierAssessment, ThirdPartyComponent } from "@/types/supplier-assessment";

const props=defineProps<{componentId:string}>();
function startGuide():void{window.dispatchEvent(new Event("crane-guide-start"))}
const component=ref<ThirdPartyComponent|null>(null),supplier=ref<Supplier|null>(null),traceability=ref<ComponentTraceability[]>([]),assessments=ref<SupplierAssessment[]>([]),notifications=ref<MaintainerNotification[]>([]),vulnerabilities=ref<ComponentVulnerabilityTrace[]>([]);
const supportState=computed<{label:string;variant:BadgeVariant}>(()=>{if(!component.value?.support_end_date)return{label:"Support unknown",variant:"neutral"};const expired=new Date(component.value.support_end_date)<new Date();return expired?{label:"Support ended",variant:"danger"}:{label:"Supported",variant:"success"}});
async function load(){const [components,suppliers,links,allAssessments,allNotifications,componentVulnerabilities]=await Promise.all([api.components(),api.suppliers(),api.traceability({component_id:props.componentId}),api.assessments(),api.notifications(),api.componentVulnerabilities(props.componentId)]);component.value=components.find(x=>x.id===props.componentId)||null;if(!component.value)return;supplier.value=suppliers.find(x=>x.id===component.value?.supplier_id)||null;traceability.value=links;assessments.value=allAssessments.filter(x=>x.supplier_id===component.value?.supplier_id&&(x.component_id===null||x.component_id===props.componentId));notifications.value=allNotifications.filter(x=>x.component_id===props.componentId);vulnerabilities.value=componentVulnerabilities}
function initials(value:string){return value.split(/\s+/).slice(0,2).map(x=>x[0]).join("").toUpperCase()}
function label(value:string){return value.replaceAll("_"," ").replace(/^./,x=>x.toUpperCase())}
function formatDate(value:string){return new Intl.DateTimeFormat(undefined,{dateStyle:"medium"}).format(new Date(value))}
function assessmentVariant(value:string):BadgeVariant{return value.startsWith("approved")?"success":value==="in_review"?"warning":value==="rejected"?"danger":"neutral"}
function severityVariant(value:string|null):BadgeVariant{return value==="critical"||value==="high"?"danger":value==="medium"?"warning":"neutral"}
onMounted(load);
</script>

<style scoped>
