.component-page{max-width:1280px;margin:0 auto;display:grid;gap:20px}.back-link{width:max-content;color:var(--color-text-muted);font-size:13px;text-decoration:none}.component-hero{display:flex;align-items:center;gap:16px;padding:24px;border:1px solid var(--color-border);border-radius:16px;background:var(--color-surface);box-shadow:0 12px 35px rgba(0,0,0,.05)}.component-mark{width:56px;height:56px;display:grid;place-items:center;border-radius:15px;background:linear-gradient(145deg,color-mix(in srgb,var(--color-primary) 80%,#3b82f6),var(--color-primary));color:white;font-weight:750}.hero-copy{min-width:0;flex:1}.eyebrow{margin:0 0 5px;color:var(--color-primary);font-size:10px;font-weight:750;letter-spacing:.1em;text-transform:uppercase}.hero-copy h1{margin:0;font-size:27px;letter-spacing:-.03em}.hero-copy p:last-child{margin:6px 0 0;color:var(--color-text-muted);font-size:13px}.hero-copy a,.usage-row a{color:var(--color-primary);font-weight:650;text-decoration:none}.summary-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.summary-grid article{display:grid;gap:5px;padding:15px;border:1px solid var(--color-border);border-radius:11px;background:var(--color-surface)}.summary-grid span{color:var(--color-text-muted);font-size:11px}.summary-grid strong{font-size:20px}.detail-grid{display:grid;grid-template-columns:minmax(0,1fr) 340px;gap:16px;align-items:start}.detail-grid main,.detail-grid aside{display:grid;gap:16px}.card{padding:20px;border:1px solid var(--color-border);border-radius:13px;background:var(--color-surface)}.section-head h2,.metadata h2{margin:0;font-size:16px}.section-head p{margin:4px 0 15px;color:var(--color-text-muted);font-size:12px}.usage-list,.record-list{overflow:hidden;border:1px solid var(--color-border);border-radius:10px}.usage-row{display:grid;grid-template-columns:1fr .8fr 1.3fr;gap:14px;padding:12px;border-bottom:1px solid var(--color-border);font-size:12px}.usage-row:last-child,.record-row:last-child{border:0}.usage-row>div{display:grid;align-content:start;gap:3px}.usage-row span,.usage-row p,.record-row span{margin:0;color:var(--color-text-muted);font-size:11px}.record-row{display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px;border-bottom:1px solid var(--color-border);color:inherit;text-decoration:none}.record-row>div{display:grid;gap:3px}.metadata dl{margin:12px 0 0}.metadata dl div{padding:9px 0;border-bottom:1px solid var(--color-border)}dt{color:var(--color-text-muted);font-size:10px;text-transform:uppercase}dd{margin:4px 0 0;overflow-wrap:anywhere;font-size:12px}.notice{padding:12px 0;border-bottom:1px solid var(--color-border)}.notice>div{display:grid;gap:2px}.notice span,.notice small{color:var(--color-text-muted);font-size:10px}.notice p,.metadata>p{font-size:12px;line-height:1.5}.empty{padding:25px;color:var(--color-text-muted);font-size:12px;text-align:center}.empty.warning{color:var(--color-danger-text)}.loading{padding:60px;color:var(--color-text-muted);text-align:center}@media(max-width:900px){.detail-grid{grid-template-columns:1fr}.summary-grid{grid-template-columns:1fr 1fr}.usage-row{grid-template-columns:1fr}}
.vulnerability-row{display:grid;gap:10px;padding:13px;border-bottom:1px solid var(--color-border)}.vulnerability-row:last-child{border:0}.vulnerability-head{display:flex;align-items:center;justify-content:space-between;gap:12px}.vulnerability-head>div{display:flex;align-items:center;gap:7px}.vulnerability-head>div:first-child{display:grid;gap:3px}.vulnerability-head span,.vulnerability-row small{color:var(--color-text-muted);font-size:11px}.affected{display:flex;align-items:center;flex-wrap:wrap;gap:6px}.affected span{color:var(--color-text-muted);font-size:10px;text-transform:uppercase}.affected a{padding:3px 7px;border-radius:6px;background:var(--color-surface-elevated);color:var(--color-primary);font-size:10.5px;text-decoration:none}
</style>
